# Poll to InService — re-run every ~30s. Serverless cold start is a few minutes
# (mostly first-use image pull).
if 'ep_serverless' not in dir():
    print('⏳ Run the serverless deploy cell (6a) first.')
else:
    print(ep_serverless.status())

# Poll to InService — re-run every ~30s.
if 'ep_instance' not in dir():
    print('⏳ Run the instance deploy cell (6b) first.')
else:
    print(ep_instance.status())

# Delete BOTH endpoints. Guarded so a kernel restart (no handles) doesn't error —
# in that case use sm_endpoints() above + sm_delete_endpoint('microvm-ep-...').
for _name in ['ep_serverless', 'ep_instance']:
    if _name in dir():
        print(sm_delete_endpoint(eval(_name)))
    else:
        print(f"(no {_name} handle — if one is still listed above, "
              f"delete it by name with sm_delete_endpoint('microvm-ep-...'))")
